-- See MVCC's hidden columns and the physical location of the row
SELECT xmin, xmax, ctid, * FROM accounts WHERE id = 7;

-- How much of the working set is served from RAM?
SELECT sum(blks_hit) * 100.0 / nullif(sum(blks_hit + blks_read), 0) AS cache_hit_pct
FROM pg_stat_database;

-- Replica lag and retained WAL per slot, run on the primary
SELECT slot_name, active,
       pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)) AS retained_wal
FROM pg_replication_slots;

SELECT application_name, replay_lag FROM pg_stat_replication;

-- Cassandra (CQL): the table is designed around the query
CREATE TABLE activity_by_user (
  user_id uuid, ts timeuuid, action text, item_id uuid,
  PRIMARY KEY ((user_id), ts)
) WITH CLUSTERING ORDER BY (ts DESC);

-- Neo4j (Cypher): friends-of-friends, not already friends
MATCH (me:User {id: $id})-[:FRIEND]->()-[:FRIEND]->(fof)
WHERE NOT (me)-[:FRIEND]->(fof) AND fof <> me
RETURN fof, count(*) AS mutual ORDER BY mutual DESC LIMIT 10;

-- cqlsh: per-request consistency
CONSISTENCY QUORUM;
UPDATE profiles SET email = 'a@new.com' WHERE user_id = 42;
SELECT email FROM profiles WHERE user_id = 42;   -- guaranteed to see the update

-- Faster but weaker: W=1, R=1 → 1 + 1 = 2, not > 3 → may read stale data
CONSISTENCY ONE;

-- CockroachDB: plain SQL, distributed underneath
BEGIN;
UPDATE accounts SET balance = balance - 50 WHERE id = 'alice';
UPDATE accounts SET balance = balance + 50 WHERE id = 'bob';
COMMIT;

-- See how a table is split into ranges and where their leaseholders are
SHOW RANGES FROM TABLE accounts;

-- Optimistic: succeed only if nobody changed the row since we read it (version 17)
UPDATE tickets
SET remaining = remaining - 1, version = version + 1
WHERE event_id = 99 AND version = 17 AND remaining > 0;
-- 1 row updated → ticket is yours;  0 rows → someone beat you, reload and retry

-- Pessimistic: lock the row for the rest of the transaction
BEGIN;
SELECT remaining FROM tickets WHERE event_id = 99 FOR UPDATE;
UPDATE tickets SET remaining = remaining - 1 WHERE event_id = 99;
COMMIT;

def run_report(params, deadline):
    if breaker.is_open():
        raise Unavailable("reports temporarily disabled")
    remaining_ms = int((deadline - time.monotonic()) * 1000) - 200
    if remaining_ms <= 0:
        raise DeadlineExceeded()
    with report_pool.connection(timeout=0.5) as conn:      # small, separate pool
        conn.execute(f"SET LOCAL statement_timeout = {remaining_ms}")
        try:
            return conn.execute(REPORT_SQL, params).fetchall()
        except QueryCanceled:
            breaker.record_failure(); raise

CREATE INDEX CONCURRENTLY jobs_pending ON jobs (created_at) WHERE status = 'pending';
CREATE INDEX CONCURRENTLY jobs_attrs   ON jobs USING gin (attrs jsonb_path_ops);
CREATE INDEX CONCURRENTLY jobs_cust    ON jobs (customer_id) INCLUDE (status);

-- Indexes that have never been used since stats reset
SELECT relname, indexrelname, pg_size_pretty(pg_relation_size(indexrelid))
FROM pg_stat_user_indexes WHERE idx_scan = 0;

-- CockroachDB: the cluster-wide clock offset bound (nodes beyond it shut themselves down)
-- set via: cockroach start --max-offset=500ms
SHOW CLUSTER SETTING server.clock.forward_jump_check.enabled;
-- Retries from uncertainty show up as transaction restarts:
SELECT * FROM crdb_internal.node_metrics WHERE name LIKE 'txn.restarts%';

CREATE TABLE analytics.fact_sales (
  sale_date DATE, product_key INT64, store_key INT64, qty INT64, revenue NUMERIC
) PARTITION BY sale_date CLUSTER BY store_key;

SELECT s.region, DATE_TRUNC(f.sale_date, MONTH) AS month, SUM(f.revenue) AS revenue
FROM analytics.fact_sales f
JOIN analytics.dim_store s USING (store_key)
WHERE f.sale_date >= '2023-01-01'
GROUP BY 1, 2 ORDER BY 1, 2;

