-- ProxySQL admin interface
INSERT INTO mysql_query_rules (rule_id, active, match_digest, destination_hostgroup, apply)
VALUES (1, 1, '^SELECT.*FOR UPDATE', 10, 1),
       (2, 1, '^SELECT',              20, 1);
UPDATE mysql_servers SET max_replication_lag = 2 WHERE hostgroup_id = 20;
LOAD MYSQL QUERY RULES TO RUNTIME; LOAD MYSQL SERVERS TO RUNTIME;

SELECT digest_text, count_star, sum_time FROM stats_mysql_query_digest
ORDER BY sum_time DESC LIMIT 5;

