-- Watch the CDC slot so it can't silently fill the disk
SELECT slot_name, active,
       pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), confirmed_flush_lsn)) AS lag
FROM pg_replication_slots WHERE slot_type = 'logical';

SELECT relname, n_live_tup, n_dead_tup, last_autovacuum
FROM pg_stat_user_tables ORDER BY n_dead_tup DESC LIMIT 5;

ALTER TABLE events SET (autovacuum_vacuum_scale_factor = 0.01,
                        autovacuum_vacuum_cost_limit  = 2000);

-- Anything holding back cleanup?
SELECT pid, state, now() - xact_start AS age, left(query, 60)
FROM pg_stat_activity WHERE state LIKE 'idle in transaction%' ORDER BY age DESC;

SELECT datname, age(datfrozenxid) FROM pg_database ORDER BY 2 DESC;   -- wraparound headroom
